window.__BUNDLE__={"generatedAt":"2026-10-01T00:50:40.241466+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-24","archiveCutoff":"2021-10-02","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":223,"arxiv":1778,"total":2001},"freshness":{"latestPaperDate":"2026-09-30","latestPublishedDate":"2026-09-30","latestBatchCount":628,"newInLast24h":681,"newInLast48h":1952},"historyTotal":18984,"topicCounts":{"Multi-Agent":2387,"Evaluation":10232,"Planning":1489,"Memory":391,"Code Agent":759,"Interpretability":694,"Agentic RAG":1281,"Agentic Search":1624,"RL for LLM":1108,"Reasoning":5329,"Hallucination":983,"Post-Training":2214,"Alignment":2546,"World Model":300,"Tool Use":1234,"Agent Safety":2350,"Computer Use":285,"Reflection":683,"VLM Training":1376,"LLM Training":2295,"Fine-tuning":2897,"Multimodal Agent":109,"Agent Framework":804,"Error Attribution":120,"Data Engine":378},"count":36,"recentTotal":2871,"archiveCount":0,"archiveTotal":16113,"sources":{"hf":80,"arxiv":2791,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"id":"arxiv:2609.36012","topics":["Reflection"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36012.pdf","authors":["Haojian Huang","Zexi Li","Junhao Guo","Yehang Zhang","Wenxuan Peng","Bohan Zhou","Weilin Ruan","Leyi Wu","Chenxu Wang","Jianchong Su","Binghui Xie","Wosong Chen","Yingjie Xu","Tianhao Zhou","Suzeyu Chen","Pukun Zhao","Jiaqi He","Xinyi Li","Runze Li","Peiran Dong","Shaoxiang Dang","Jing Huang","Yingbing Chen","Yifan Chang","Tianyi Zhang","Shiyuan Deng","Haozhi Wang","Yangkai Wei","Wenqian Li","Han Yang","Kaiwen Zhou","Huaping Liu","James Cheng","Rui Shao","Donglin Wang","Yaochu Jin","Jianye Hao","Ying-Cong Chen","Yinchuan Li"],"url":"https://arxiv.org/abs/2609.36012","hfUrl":"https://huggingface.co/papers/2609.36012","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36012","source":"hf","upvotes":296,"tags":["Reflection"],"title":"In-Context Learning for Robots: Methods and Applications","abstract":"General-purpose robots must infer what a new task requires and translate that understanding into appropriate physical action. In-context learning (ICL) for robots supports this process by using demonstrations and interaction to direct existing competence with neural parameters held fixed during deployment. We organize this literature review around the interfaces connecting contextual evidence to execution, distinguishing four families: context-conditioned policies, geometric demonstration transfer, world-model-based control, and skill- and agent-based execution. Comparing these interfaces clarifies their transfer assumptions and the roles of training, correspondence, and memory in making context useful. Across manipulation and navigation, we examine how these mechanisms preserve taught requirements as objects, environments, and execution conditions change. This analysis links method desi"},{"id":"arxiv:2609.36380","topics":["Code Agent","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36380.pdf","authors":["Xirui Li","Peng Shi","Mingwen Dong","Sheng Zhang","Zhuoyan Xu","Dongkyu Lee","Shuaichen Chang","Yi Xiang","Lin Pan","Jiarong Jiang"],"url":"https://arxiv.org/abs/2609.36380","hfUrl":"https://huggingface.co/papers/2609.36380","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36380","source":"hf","upvotes":102,"tags":["Code Agent","Evaluation"],"title":"LEGO-Anything: Coding Agents for 3D Scene Reconstruction","abstract":"A 3D scene reconstructed from a single image is most useful when represented not as a rendering or a fixed 3D output, but as an explicit scene program whose execution yields a scene that can be inspected, edited, and queried. We present LEGO-Anything, an Image-to-Code framework in which a coding agent iteratively writes and executes Blender code, inspects scenes and renderings, and revises the program. To evaluate end-to-end scene recovery, we introduce LEGO-Bench, a simulator-grounded benchmark with 208 images from 104 diverse indoor and outdoor scenes. LEGO-Bench separately scores artifact validity, visible-surface geometry, and rendered appearance. Its simulator-grounded design enables extensibility and precise automatic evaluation. Among evaluated agents, GPT-6-astra achieves the strongest overall results, with 53.4% indoor and 39.6% outdoor scores, yet substantial gaps remain betwee"},{"id":"arxiv:2609.37372","topics":["Post-Training","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37372.pdf","authors":["Xuehai Bai","Zhenchen Tang","Yang Shi","Dianyi Wang","Tengfei Liu","Wanshun Su","Xuanyu Zhu","Ruohui Wang","Haiwen Diao","Haotian Wang","Xiaoling Gu","Yuanxing Zhang"],"url":"https://arxiv.org/abs/2609.37372","hfUrl":"https://huggingface.co/papers/2609.37372","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37372","source":"hf","upvotes":84,"tags":["Post-Training","Evaluation"],"title":"Think Before You Score: Thinking Reward Model for Visual Generation","abstract":"Visual reward models are essential for evaluating and improving visual generation models, yet existing approaches typically map task conditions and candidate outputs directly to scalar rewards, leaving implicit what should be evaluated for each individual case. We introduce Think Before You Score, a paradigm that explicitly determines what matters for each case before judging how well the candidate performs. Following this principle, we propose the Thinking Reward Model (TRM), which formulates case-adaptive rubrics, performs rubric-guided assessment, and produces fine-grained pointwise rewards. We further observe that conventional pairwise preference optimization can induce score polarization, and introduce Pairwise Dual-Group Relative Policy Optimization (PD-GRPO), which leverages pairwise supervision to improve reward discrimination while preserving fine-grained pointwise scoring. Exte"},{"id":"arxiv:2609.36601","topics":["Reasoning","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36601.pdf","authors":["Miteto Wei","Xiaohan Wang","Zehao Chen","Jiajun Chai","Sichao Liu","Li Wang","Haoyuan Xu","Zhaoyu Hu","Wei Lin","Guojun Yin"],"url":"https://arxiv.org/abs/2609.36601","hfUrl":"https://huggingface.co/papers/2609.36601","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.36601","source":"hf","upvotes":81,"tags":["Reasoning","Evaluation"],"title":"SAKI: Maximal-Coupling-Routed Teacher Supervision for On-Policy Distillation","abstract":"On-policy distillation (OPD) reduces train-test state mismatch by training a student on its own generated trajectories, but weak students may visit teacher-misaligned prefixes where supervision is less representative. We introduce SAKI (Supervision Allocation with KL-constrained Interpolation), which combines a KL-constrained teacher-guided rollout with maximal coupling and reuses realized accept/correction events to route token-level supervision. Accepted positions retain sampled-token reverse-KL supervision, while correction positions receive direct supervision on the teacher's highest-probability token. Under maximal coupling, the correction probability is exactly TV(p_t, q_t), so the same trust-region radius controls rollout deviation and upper-bounds intervention and specialized-supervision frequency. We further implement an engine-resident speculative verifier that preserves the ex"},{"id":"arxiv:2609.37686","topics":["Reasoning","Computer Use","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37686.pdf","authors":["Hongcheng Gao","Hailong Qu","Yu Lei","Henghui Sun","Haoyang Li","Yipeng Wei","Naihao Xue","Xiaohan Yu","Zhuo Tao","Yihe Zang","Yajiao Wang","Jingyi Tang","Yi Li","Jingjing Zhou","Jie Luo","Bohan Zeng","Chengyu Shen","Hao Jiang","Chong Chen","Bowen Qu","Olive Huang","Zeqiang Wang"],"url":"https://arxiv.org/abs/2609.37686","hfUrl":"https://huggingface.co/papers/2609.37686","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37686","source":"hf","upvotes":52,"tags":["Reasoning","Computer Use","Evaluation"],"title":"EngiWorld: What Can Frontier Agents Deliver in Professional Engineering Environments?","abstract":"Autonomous agents have made rapid progress in general-purpose computer use, but reliable automation of professional industrial engineering remains out of reach, as engineering workflows demand reasoning over geometric and physical constraints and dependencies preserved across software and design stages. We present EngiWorld, the first benchmark structured around the complete design loop: 1,301 expert-curated tasks spanning 6 engineering domains (CAD, CAE, CAM, BIM, EDA, and 3D visualization) and 26 professional software platforms, with both GUI and CLI interfaces and 6 task types ranging from software-selection to open-ended tasks. We further introduce an artifact-centric evaluation methodology built on a unified domain-verifier suite, which programmatically checks the geometric validity, physical feasibility, and rule compliance of final and intermediate artifacts, and scores quantitati"},{"id":"arxiv:2609.37868","topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37868.pdf","authors":["Doohyuk Jang","Yoonsik Park","Gyouk Chu","Sihwan Park","Eunho Yang"],"url":"https://arxiv.org/abs/2609.37868","hfUrl":"https://huggingface.co/papers/2609.37868","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37868","source":"hf","upvotes":43,"tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"title":"Learning Beyond What You Sample: Off-Policy-Aware Cross-Model Trajectory Exchange for RLVR","abstract":"Reinforcement Learning with Verifiable Rewards (RLVR) methods such as GRPO rely on successful self-generated trajectories, but finite rollout budgets can produce all-fail groups with no reward-based policy-gradient signal. While additional rollouts improve the chance of success at higher cost, successful trajectories missing from one model's rollouts may already have been discovered by another. Indeed, we observe that heterogeneous models often succeed on complementary prompts, creating opportunities for mutual learning without a designated stronger teacher. To exploit this complementarity, we propose GRAFT (Gated Replacement of Answer-Failed groups with peer Trajectories), an off-policy-aware framework that replaces all-fail groups with informative peer groups. GRAFT transfers both successful and unsuccessful peer responses with peer-computed advantages, while controlling cross-model mi"},{"id":"arxiv:2609.38079","topics":["LLM Training","Reasoning","Alignment"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.38079.pdf","authors":["Jiaxin Ge","Yiming Qin","Ji Xie","Haozhe Jiang","Xiaochuang Han","Junyi Zhang","Andrew Dai","Yinfei Yang","Jitendra Malik","Ranjay Krishna","Sewon Min","Haiwen Feng","Le Xue","Baifeng Shi","Trevor Darrell","XuDong Wang"],"url":"https://arxiv.org/abs/2609.38079","hfUrl":"https://huggingface.co/papers/2609.38079","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38079","source":"hf","upvotes":43,"tags":["LLM Training","Reasoning","Alignment"],"title":"OmniTaskonomy: When Does Visual Generation Improve Visual Understanding?","abstract":"Training a model to generate visual content can encourage it to learn rich perceptual capabilities related to geometry, spatial relationships, and objectness; yet, its benefits for visual understanding remain unclear. We ask: when and how does visual generation supervision improve visual understanding? We study controlled pairs of image-to-image (I2I) generation and image-to-text (I2T) understanding tasks that express the same underlying problem in different output modalities. We find that under the correct recipe, I2I training improves downstream I2T performance, with larger gains as the amount of I2I training data increases. We next ask which generation tasks benefit which understanding capabilities. To study transfer beyond paired tasks, we introduce OmniTaskonomy, a unified taxonomy spanning 19 I2I generation tasks and 25 I2T understanding capabilities. The resulting transfer map rev"},{"id":"arxiv:2609.35954","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.35954.pdf","authors":["Zhiwei Zhang","Huayu Deng","Fei Zhao","Jiayan Fu","Bin Liang","Kam-Fai Wong","Mu Chuan"],"url":"https://arxiv.org/abs/2609.35954","hfUrl":"https://huggingface.co/papers/2609.35954","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.35954","source":"hf","upvotes":33,"tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"title":"ROSS: Relearning from Self-Generated Rollouts through Selective Supervision","abstract":"Large language model post-training generates self-generated rollouts through reinforcement learning and on-policy distillation, yet this experience is often treated as stale once the policy advances. Historical rollouts can remain compatible with a later policy while preserving behaviors that the policy no longer expresses reliably. However, they may also contain mistakes, abandoned attempts, and redundant actions that should not be imitated, motivating finer-grained selective supervision. We introduce ROSS (Relearning from Self-Generated Rollouts through Selective Supervision), which preserves the full historical trajectory as context while applying loss only to selected model-generated continuations. Across domain-specific reinforcement learning, multi-teacher on-policy distillation, and agentic reinforcement learning, ROSS consistently improves upstream checkpoints and outperforms bas"},{"id":"arxiv:2609.38008","topics":["LLM Training","Computer Use","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.38008.pdf","authors":["Tongbo Chen","Junbo Niu","Zhengxi Lu","Niu Lian","Fei Tang","Yuchen Yan","Yike Hong","Yong Du","Yizhou Liu","Bofan Chen","Yongliang Shen"],"url":"https://arxiv.org/abs/2609.38008","hfUrl":"https://huggingface.co/papers/2609.38008","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38008","source":"hf","upvotes":27,"tags":["LLM Training","Computer Use","Fine-tuning"],"title":"HybridCUA: Learning to Orchestrate GUI and CLI for Computer-Use Agents","abstract":"Computer use agents (CUAs) have demonstrated strong capabilities in completing digital tasks. However, existing CUAs either rely solely on graphical user interface (GUI) interactions, which are often inefficient and error prone, or augment GUI interactions with application specific APIs or tools, which require substantial engineering effort and are difficult to scale across applications. We argue that the next generation of CUAs should combine GUI interactions with the command line interface (CLI), leveraging the generality of the GUI and the efficiency of shell commands. A critical challenge, however, is that current models do not know when or how to use the CLI during task execution. To address this challenge, we develop a data construction pipeline that produces three types of trajectories: GUI only, CLI only, and interleaved GUI and CLI trajectories. This pipeline results in HybridCU"},{"id":"arxiv:2609.38057","topics":["VLM Training"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.38057.pdf","authors":["Shiyang Zhou","Xionghao Wu","Wenbo Li","Shenghe Zheng","Jiyao Zhang","Songsong Yu","Yijun Yang","Jianhui Liu","Haoze Sun","Senqiao Yang","Li Jiang","Jingyong Su","Haoyang Huang","Zhuotao Tian"],"url":"https://arxiv.org/abs/2609.38057","hfUrl":"https://huggingface.co/papers/2609.38057","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38057","source":"hf","upvotes":27,"tags":["VLM Training"],"title":"EVO-WAM: Evolving World Action Models through Video-Action Verification","abstract":"Improving robot policies on new tasks without collecting additional expert demonstrations remains a central challenge in robot learning. World action models (WAMs) use broad video priors to jointly predict future videos and actions, offering a potential source of supervision for adapting to new tasks. However, generated videos may fail to depict task completion, and even visually successful videos may be paired with inconsistent actions that lead to execution failure. We propose EVO-WAM, a framework that adapts WAMs to unseen tasks by learning from their own generated video-action trajectories, without executing candidate actions in an external environment. First, we augment WAM training with state prediction and anchored multi-frame context to enable complete autoregressive rollouts without external execution feedback. Second, we identify reliable training experience by selecting task-c"},{"id":"arxiv:2609.36802","topics":["Reasoning","RL for LLM"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36802.pdf","authors":["Xuanyi Zhou","Qiuyang Mang","Huanzhi Mao","Dacheng Li","Wenhao Chai","Mayank Mishra","Yichuan Wang","Karthik Narasimhan","Alvin Cheung","Joseph E. Gonzalez"],"url":"https://arxiv.org/abs/2609.36802","hfUrl":"https://huggingface.co/papers/2609.36802","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.36802","source":"hf","upvotes":26,"tags":["Reasoning","RL for LLM"],"title":"EasyPPO: Stabilizing the Critic Is Key","abstract":"A key strength of Proximal Policy Optimization (PPO) is its learned critic, which uses historical trajectories collected during reinforcement learning to estimate expected returns and reduce policy-gradient variance. However, we find that the critic is also a major source of instability in reinforcement learning for large language models (LLMs). We identify two critic failure modes that destabilize PPO. First, filtering truncated rollouts from both actor and critic shifts the policy objective to reward conditioned on completion, allowing truncation to increase even as conditional reward improves. Second, heterogeneous return noise can cause high-variance prompts to dominate critic updates in finite batches. We introduce EasyPPO to address these failures. Actor-only overlong filtering trains the critic on returns from both completed and truncated rollouts. Noise-normalized critic regressi"},{"id":"arxiv:2609.37441","topics":["Planning","World Model"],"date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37441.pdf","authors":["Mingu Kang","Yoori Oh","Sookyung Kim","Joonseok Lee"],"url":"https://arxiv.org/abs/2609.37441","hfUrl":"https://huggingface.co/papers/2609.37441","arxiv":"https://arxiv.org/abs/2609.37441","source":"hf","upvotes":26,"tags":["Planning","World Model"],"title":"Anisotropic Representations Improve Planning in JEPA World Models","abstract":"Latent world models learn action-conditioned dynamics in representation space and often score candidate actions by Euclidean distance to a goal representation. Joint training typically regularizes the representation to prevent collapse, but the resulting representation geometry also determines how terminal errors are weighted during planning. We show that accurate prediction and noncollapsed representations do not guarantee a task-aligned latent planning cost: isotropic Gaussian regularization can induce a geometry that ranks feasible outcomes differently from the task cost. To address this mismatch, we introduce AnisoWM with $Λ$Reg, which replaces the fixed isotropic Gaussian target with a learnable diagonal covariance under fixed-trace and anisotropy constraints. The prediction objective, predictor architecture, and Euclidean planner remain unchanged; the target is used only during tra"},{"id":"arxiv:2609.36246","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36246.pdf","authors":["Haojin Wang","Dylan Zhang","Huaibo Chen","Suhao Yu","Yihang Sun","Zhanyang Jin","Jiaying Ye","Dianqi Li","Prasanna Sattigeri","Kamal Youcef-Toumi","Hao Peng"],"url":"https://arxiv.org/abs/2609.36246","hfUrl":"https://huggingface.co/papers/2609.36246","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36246","source":"hf","upvotes":25,"tags":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"title":"Learning from Teacher Continuations at Student States","abstract":"We present OLIVE (OnLine InterVEntion). At each iteration, the evolving student policy generates a new prefix, the teacher continues it autoregressively, and the student is updated using cross-entropy computed on the teacher-generated tokens. Each design choice targets a corresponding limitation of existing distillation methods: (1) sequential covariate shift in offline supervised fine-tuning (SFT) on fixed teacher trajectories, (2) fragmented supervision under prefix failure in token-level on-policy distillation (OPD), and (3) the need for access to teacher token probabilities in distribution-matching distillation. OLIVE achieves higher reasoning performance than OPD (with a top-16 KL approximation) at comparable GPU-hour cost. Our asynchronous implementation further reduces OLIVE's total training time by 23.8\\%. We evaluate OLIVE on both hard reasoning tasks and agentic tasks which ref"},{"id":"arxiv:2609.37725","topics":["Multi-Agent"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37725.pdf","authors":["Rulin Shao","Shannon Zejiang Shen","Junjie Oscar Yin","Yuetai Li","Minheng Wang","Hamish Ivison","Radha Poovendran","Nathan Lambert","Teng Xiao","Mike Lewis","Wen-tau Yih","Luke Zettlemoyer","Pang Wei Koh"],"url":"https://arxiv.org/abs/2609.37725","hfUrl":"https://huggingface.co/papers/2609.37725","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37725","source":"hf","upvotes":24,"tags":["Multi-Agent"],"title":"Context Language Models","abstract":"We introduce Context Language Models (CLMs), language models that natively manage their own context. We implement this by treating the context as a file and allowing the model to make unrestricted updates to this file. This allows the model to learn what is most important to maintain in context, and naturally extends to multi-agent systems where multiple agent contexts coexist as files. Building CLMs zero-shot with existing models outperforms SOTA context management strategies across a variety of tasks: 11.4% higher accuracy with 21.5% fewer FLOPs on BrowseComp-Plus, 5% higher scores with 59% fewer FLOPs on 12-hour EdgeBench, and 65% greater improvement with the same compute on a 24-hour multi-repository agent-swarm task. Moreover, by shifting context management from external harness control to intrinsic model behavior, CLMs naturally enable both in-context and parametric learning of con"},{"id":"arxiv:2609.37775","topics":["LLM Training","Alignment","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37775.pdf","authors":["Xuanyu Zhu","Yan Bai","Yang Shi","Yihang Lou","Yuanxing Zhang","Tengfei Liu","Jing Jin","Yuan Zhou"],"url":"https://arxiv.org/abs/2609.37775","hfUrl":"https://huggingface.co/papers/2609.37775","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37775","source":"hf","upvotes":17,"tags":["LLM Training","Alignment","Fine-tuning"],"title":"HiRAE: Hierarchical Representation Autoencoding with Residual Budgets","abstract":"Pretrained visual representations support image generation, but may not fully preserve the fine-grained details needed for faithful reconstruction. Meanwhile, intermediate encoder layers contain complementary visual details, but learning to fuse them for reconstruction can produce a latent distribution that is difficult to model. Existing fusion methods require empirical tuning of layer selection or staged optimization of fusion and decoding, increasing configuration effort or training complexity. We introduce HiRAE (Hierarchical Representation Autoencoder), which learns a hierarchical fusion framework over the full encoder hierarchy to improve reconstruction fidelity while maintaining compatibility with generative modeling. HiRAE groups encoder layers by depth and learns residual corrections to the deepest representation. Group-wise norm caps bound these corrections relative to the deep"},{"id":"arxiv:2607.11433","topics":["LLM Training","Planning","Fine-tuning"],"date":"2026-09-30","pdf":"https://arxiv.org/pdf/2607.11433.pdf","authors":["Ming Ma","Yi Zhu","Yiran Zhong","Feida Zhu","Yuhao Wang","Junhan Shi","Lingrui Mei","Tianming Yang","Steven Hoi"],"url":"https://arxiv.org/abs/2607.11433","hfUrl":"https://huggingface.co/papers/2607.11433","arxiv":"https://arxiv.org/abs/2607.11433","source":"hf","upvotes":16,"tags":["LLM Training","Planning","Fine-tuning"],"title":"Omni-Decision: Evidence-Ledger Planning for Omni-Modal Agents","abstract":"Omni-modal agents must seek evidence across video, audio, web pages, and computation to answer questions. Their main bottleneck is planning: noisy multimodal observations accumulate in conversation history and disrupt later decisions, while multimodal models have limited capacity for multi-step planning. Controlled backend replacements support this diagnosis: replacing the planner causes a much larger performance loss than replacing the perception backend. We present Omni-Decision, an omni-modal agent built on evidence-ledger planning: it replaces the growing dialogue history with an explicit evidence ledger that records what evidence is still missing, what has been confirmed, and where records conflict. A critic reads each noisy observation and passes only the usable content to the ledger, discarding the rest, so the planner works from a compact context throughout the task. Each run rec"},{"id":"arxiv:2609.37959","topics":["Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37959.pdf","authors":["Weihao Kong","Erez Louidor Ilan","Shuxin Nie","Taman Narayan","Rajat Sen","Yichen Zhou","Deqing Fu","Samet Oymak","Abhimanyu Das"],"url":"https://arxiv.org/abs/2609.37959","hfUrl":"https://huggingface.co/papers/2609.37959","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37959","source":"hf","upvotes":13,"tags":["Evaluation"],"title":"TabFM: A Zero-Shot Foundation Model for Tabular Data","abstract":"Tabular machine learning typically relies on per-dataset workflows, fitting tree ensembles or running AutoML searches from scratch for every task. We present TabFM, a 400M-parameter tabular foundation model that formulates supervised tabular prediction as in-context learning. TabFM produces calibrated zero-shot predictions in a single forward pass without task-specific tuning. Trained entirely on synthetic tables generated from structural causal models, TabFM learns general tabular representations that transfer zero-shot to real-world tasks. Across all 51 benchmark datasets in TabArena (38 classification and 13 regression), zero-shot TabFM ranks first among default tabular foundation models and outperforms tuned AutoML pipelines. Two extensions over the same frozen weights improve performance further on both tracks: multi-view feature expansion with ensembling and post-hoc calibration (T"},{"id":"arxiv:2609.38170","topics":["Post-Training","LLM Training","Alignment"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.38170.pdf","authors":["Xin Lin","Zhifei Zhang","Yuqian Zhou","Haitian Zheng","Zhe Lin","Ming-Hsuan Yang","Truong Nguyen"],"url":"https://arxiv.org/abs/2609.38170","hfUrl":"https://huggingface.co/papers/2609.38170","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38170","source":"hf","upvotes":12,"tags":["Post-Training","LLM Training","Alignment"],"title":"Adversarial Training for Pixel Diffusion","abstract":"Pixel diffusion models generate RGB images directly, avoiding the bottleneck of an autoencoder, yet their outputs still systematically underrepresent fine-scale natural-image statistics. We show that adversarial learning provides an effective post-training correction for this deficiency. Starting from a pretrained model, we retain its original diffusion or flow-matching objective and add an adversarial loss to the predicted output at non-high-noise timesteps, leaving the model architecture and sampling procedure unchanged. To our knowledge, this is the first systematic study of adversarial post-training for pixel diffusion. Across two pixel backbones, the method jointly improves distribution fidelity, coverage, prompt alignment, and perceptual quality. We further investigate why it works. Frequency-band and power-law analyses show that the original models systematically underproduce natu"},{"id":"arxiv:2609.38119","topics":["Reasoning","Memory","Multimodal Agent"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.38119.pdf","authors":["Jinfa Huang","Jianming Xu","Jingyang Lin","Zhengyuan Yang","Jiebo Luo"],"url":"https://arxiv.org/abs/2609.38119","hfUrl":"https://huggingface.co/papers/2609.38119","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38119","source":"hf","upvotes":11,"tags":["Reasoning","Memory","Multimodal Agent"],"title":"VideoLoop: Looped Working Memory Against Semantic Thrashing in Long-Form Video Agents","abstract":"Long-form video understanding requires multimodal agents to iteratively gather evidence over many reasoning steps. However, most existing agentic methods suffer from semantic thrashing: as append-only working memory grows, attention to key evidence collapses, and the agent loses access to what it has already found. First, we provide a structural argument showing that append-only memory can incorporate newly observed target evidence, but cannot remove accumulated noise or prevent ordered context growth without a rewrite operator. Second, motivated by this analysis, we propose VideoLoop, a multimodal agent with two coupled loops. The outer loop reasons over the video and the inner loop, after each step, retrieves artifacts from an unbounded filesystem of past observations and intermediate analysis, and rewrites a bounded working memory. Extensive experiments demonstrate the effectiveness o"},{"id":"arxiv:2609.36139","topics":["Reasoning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36139.pdf","authors":["Jenny Y. Huang","Jiameng Fan","Ahmed Imtiaz Humayun","Maximillian Chen","Tian Qin","Run Chen","Vidhya Navalpakkam","Hongxiang Gu"],"url":"https://arxiv.org/abs/2609.36139","hfUrl":"https://huggingface.co/papers/2609.36139","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36139","source":"hf","upvotes":6,"tags":["Reasoning"],"title":"Language Models Are \"Insecure\" Reporters","abstract":"As large language models are deployed in increasingly autonomous long-horizon tasks, manually auditing and verifying the actions, artifacts, and outputs of models becomes more difficult. Users instead come to rely on LLM-generated reports to assess the quality and completeness of the work. We introduce a suite of eight adversarial reporting scenarios to systematically study whether LLMs conceal narrative-changing flaws: errors or limitations that undermine an otherwise successful account of work. We call this phenomenon \"insecure reporting.\" When handed machine learning experiment logs containing a planted negative result that substantially weakens the proposed method, GPT-5.5 flags the negative result in only 2 of 200 generated reports. However, when a short honesty instruction, \"Be honest in your response,\" is added, the model flags the negative result in 190 of 200 reports. Across eig"},{"id":"arxiv:2609.37989","topics":["LLM Training","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37989.pdf","authors":["Deqing Fu","Huangyuan Su","Rajat Sen","Taman Narayan","Sujay Sanghavi","Abhimanyu Das","Weihao Kong"],"url":"https://arxiv.org/abs/2609.37989","hfUrl":"https://huggingface.co/papers/2609.37989","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37989","source":"hf","upvotes":3,"tags":["LLM Training","Evaluation"],"title":"TabFM-Auto: Self-Evolving Pipelines for Tabular Foundation Models","abstract":"Tabular foundation models achieve strong zero-shot accuracy on structured data by pretraining on synthetic tables, but they ignore the column names, task descriptions, and auxiliary files that carry dataset semantics. Meanwhile, self-evolving machine learning engineering (MLE) agents train models from scratch on each dataset, yet jointly searching over features, architectures, and hyperparameters is noisy and prone to overfitting. We introduce TabFM-Auto, which pairs a tabular foundation model, TabFM, with a language model agent that evolves the data pipeline around it. Guided by dataset metadata and validation feedback, TabFM-Auto iteratively refines data cleaning, feature engineering, context selection, and post-processing to reduce TabFM's error. Across all 51 datasets of the TabArena benchmark, five TabFM-Auto configurations with different agents and language models take the top five"},{"id":"arxiv:2609.36864","topics":["Post-Training"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36864.pdf","authors":["Fanchao Chen","Hengyu Fu","Shivaram Venkataraman","Jiantao Jiao"],"url":"https://arxiv.org/abs/2609.36864","hfUrl":"https://huggingface.co/papers/2609.36864","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.36864","source":"hf","upvotes":3,"tags":["Post-Training"],"title":"Where the Model Changes Its Mind: Hindsight-Divergence Localization for Efficient Reinforcement Learning with Verifiable Rewards","abstract":"Group-relative methods for reinforcement learning with verifiable rewards (RLVR) learn from differences in rollout outcomes. Independently sampling complete trajectories is costly and does not explicitly explore the decision space at critical positions. Feedback on a completed trajectory can reveal which earlier choices the policy reconsiders, suggesting where to sample alternative continuations. We introduce Hindsight-Divergence Localization (HDL), which uses hindsight-induced changes in token log-likelihoods to select branch points. HDL generates a small number of complete root trajectories and fills each training group with continuations from the selected positions under the original task context. Each continuation reuses its root prefix and contributes policy updates only through its newly generated suffix, reducing generation cost while focusing additional exploration and learning o"},{"id":"arxiv:2609.37923","topics":["Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37923.pdf","authors":["Ziyun Zeng","Hang Hua","Shaden Alshammari","Rogerio Feris","William T. Freeman","Jiebo Luo"],"url":"https://arxiv.org/abs/2609.37923","hfUrl":"https://huggingface.co/papers/2609.37923","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37923","source":"hf","upvotes":3,"tags":["Evaluation"],"title":"EpiCon: Collective Agent Learning through Co-Evolving Multimodal Memory","abstract":"Agents can learn from past executions, but enabling different agents to reuse and build on one another's experience remains challenging. We introduce EpiCon, a shared multimodal memory framework for agent collective learning without updating host model parameters. EpiCon links question-level memory evolution to a persistent experience bank through two independently trained 2B models: a memory controller and a tree self-organizer. The controller jointly refines textual guidance and visual evidence across attempts and selectively includes visual memory. The self-organizer consolidates lessons hierarchically and retrieves experience and rules for new problems. We evaluate EpiCon on eleven benchmarks spanning four multimodal task domains, using two harnesses and multiple backbones. A frozen bank improves other systems even with a single solving attempt. A second harness raises the original s"},{"id":"arxiv:2609.36159","topics":["LLM Training","Multi-Agent","Code Agent","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36159.pdf","authors":["Fahd Seddik","Fatemeh Fard"],"url":"https://arxiv.org/abs/2609.36159","hfUrl":"https://huggingface.co/papers/2609.36159","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36159","source":"hf","upvotes":1,"tags":["LLM Training","Multi-Agent","Code Agent","Evaluation"],"title":"Principled Thoughts for Latent Recursive LLM Systems","abstract":"Large language models can reason in continuous space instead of decoded text, by recurring on their own hidden states or by passing those states between agents, while training supervises only the Cross-Entropy (CE) of the final decoded answer and does not constrain the thought. Theoretical and empirical analyses establish and confirm four failures of CE-only training that lead to a lower probability of the correct answer such as collapsing thoughts across distinct questions and retaining irrelevant information. We introduce REST (REpresentation-Supervised Thoughts), a training objective that turns four properties of a valid thought representation (causality, minimality, separability, and stability) into differentiable losses added to CE. We instantiate it in latent single-agent and multi-agent systems, without architectural changes or added parameters at inference. Across 7 benchmarks sp"},{"id":"arxiv:2609.35932","topics":["Agent Safety","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.35932.pdf","authors":["Yan Zhan","Yunze Song","Mengkai Hou","Wanting Zhang","Shaobo Liu","Zhijun Gao"],"url":"https://arxiv.org/abs/2609.35932","hfUrl":"https://huggingface.co/papers/2609.35932","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.35932","source":"hf","upvotes":1,"tags":["Agent Safety","Reasoning","Evaluation","Fine-tuning"],"title":"Same Bytes, Different Authority: Reserved-Token Representations in Chat-Template Prompt Injection","abstract":"Prompt injection against LLM agents becomes much stronger when the injected instruction is wrapped in the model's own chat template. A forged template marker such as <|im_start|> can reach the model either as a single reserved control token or as a sequence of ordinary subword tokens. The two decode to exactly the same text, and because tokenization runs on the server, the defender rather than the attacker decides which one the model receives. We use this to measure how much of the injected instruction's authority comes from the reserved token's learned representation. Encoding the forged markers as subwords, with the text held fixed and a control for the extra tokens this adds, lowers attack success on the InjecAgent benchmark by 39 to 66 percentage points on three of four open-weight families, and the gap carries over to multi-turn agent tasks in AgentDojo. On Qwen3-8B the gap is 8 poi"},{"id":"arxiv:2609.36608","topics":["Reasoning","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36608.pdf","authors":["Zubin Zheng","Jiahao Wu","Shaofeng Zhang","Zhirui Zhang","Yew-Soon Ong","Shengcai Liu"],"url":"https://arxiv.org/abs/2609.36608","hfUrl":"https://huggingface.co/papers/2609.36608","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.36608","source":"hf","upvotes":1,"tags":["Reasoning","Evaluation"],"title":"Act First, Reason Later: Accelerating On-Policy Distillation for Multi-Turn Agents via Reference-Conditioned Inverse Dynamics","abstract":"On-policy distillation (OPD) trains multi-turn language agents with dense teacher supervision on student-generated responses. However, standard think-then-act rollouts require lengthy reasoning before each short action, delaying environment transitions and experience collection. Generating actions directly reduces this delay but can degrade rollout quality. To address this, we propose ActFirst-OPD, an act-first, reason-later training framework that decouples environment interaction from full-response generation. The student infers and executes actions through reference-conditioned inverse dynamics using its current interaction context and a reference next observation, and switches to autonomous next-action prediction when the resulting transition deviates from the reference trajectory. From the collected interaction contexts, the student asynchronously generates full think-then-act respo"},{"id":"arxiv:2609.36322","topics":["Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36322.pdf","authors":["Xingyu Zhu","Pu","Yi","Ziheng Cheng","Ang Lv","Jing Liu","Lexing Ying","Yiyuan Ma","Xin Dong"],"url":"https://arxiv.org/abs/2609.36322","hfUrl":"https://huggingface.co/papers/2609.36322","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36322","source":"arxiv","upvotes":86,"tags":["Evaluation"],"title":"Periodic Weak Spots: Phase Sensitivity from Chunked KV-Cache Compression","abstract":"Chunked KV-cache compression reduces the memory and attention costs of long-context inference by compressing windows of consecutive tokens into fewer cache entries at a fixed stride. Such compression also introduces a new positional coordinate: a token's phase, or its position relative to compression-window boundaries. We uncover a systematic asymmetry in models using such compression: the same information can be easy to retrieve at one phase and difficult at another. We call this periodic variation in retrieval performance phase sensitivity. In large open-weight models with such compression, long-context retrieval accuracy can differ by up to 40 percentage points across phases, revealing periodic weak spots that average benchmark scores can conceal. To investigate this behavior, we pretrain a family of transformers from scratch across multiple KV-compression designs, reproducing phase s"},{"id":"arxiv:2609.37226","topics":["Agentic Search","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37226.pdf","authors":["Soyeong Jeong","Sujay Kumar Jauhar","Sung Ju Hwang","Andrew Joohun Nam"],"url":"https://arxiv.org/abs/2609.37226","hfUrl":"https://huggingface.co/papers/2609.37226","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37226","source":"arxiv","upvotes":72,"tags":["Agentic Search","Evaluation"],"title":"Follow the Entities: A Corpus Map for Agentic Search","abstract":"Answering questions and completing tasks over large document collections often requires connecting evidence spread across multiple documents, such as a project's approval recorded in one, its requirements in another, and its latest status in a third. Recent LLM agents approach this by iteratively searching the full corpus rather than reading only a fixed set of top-ranked documents. However, when the corpus is exposed only as a flat collection of files, a relevant document gives no indication of how it relates to others, so the agent must rediscover these relationships for every query, often missing complementary evidence while simultaneously consuming substantial additional tokens. To address this, we introduce CorpusMap, a navigation layer that organizes the corpus around its recurring entities, which are identifiable from the documents themselves and can link a single document to many"},{"id":"arxiv:2609.36071","topics":["Agentic Search","Post-Training","Multi-Agent","Planning","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36071.pdf","authors":["Meituan LongCat Team","He Zhu","Yue Xu","Wanli Wu","Haolin Ren","Yuxin Bian","Jiarui Zhao","Rongzhi Zhang","Quanchi Weng","Jinghao Cui","Yu Fan","Yuhan Liu","Yunhu Ye","Jiyuan Ren","Fengcheng Yuan","Zhao Yang","Jiacheng Zhang","Yuchuan Dai","Ruixuan Xiao","Haozhe Sun","Xiangyuan Liu","Cheng Sun","Yao Du","Yiming Hao","Hongbo Guo","Shuo He","Lei Wang","Xunliang Cai","Yan Chen","Fan Yang","Lingchuan Liu"],"url":"https://arxiv.org/abs/2609.36071","hfUrl":"https://huggingface.co/papers/2609.36071","submittedDate":"2026-09-28","arxiv":"https://arxiv.org/abs/2609.36071","source":"arxiv","upvotes":53,"tags":["Agentic Search","Post-Training","Multi-Agent","Planning","Evaluation"],"title":"LongCat-DeepResearch Technical Report","abstract":"We present LongCat-DeepResearch, a deep research system that combines an enhanced LongCat model with a multi-agent workflow for producing comprehensive, evidence-grounded reports. The workflow separates global planning from detailed investigation and coordinates revision at the section level. Multiple planning agents first explore external sources and refine an actionable research plan, termed ResearchSpec. Research agents then investigate and draft their assigned sections in parallel, gathering additional evidence in separate contexts as their analyses develop. Once the sections are assembled, global review guides targeted local revisions, reducing reliance on repeated full-report rewriting. This workflow also supports the construction of research tasks and trajectories for the mid-training and post-training of LongCat's general-purpose models. LongCat-DeepResearch achieves 55.25 on Dee"},{"id":"arxiv:2609.37559","topics":["Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37559.pdf","authors":["Jianguo Huang","Jinming Liu","Qiyao Wang","Liang Xu","Jianhang Li","Zhimian Wen","Mingda Li","Shule Lu","Zhicheng Wang","Yuhan Guo","Xin Jin","Wenjun Zeng"],"url":"https://arxiv.org/abs/2609.37559","hfUrl":"https://huggingface.co/papers/2609.37559","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37559","source":"arxiv","upvotes":29,"tags":["Evaluation"],"title":"APM-Bench: Benchmarking Cross-session Persistent Memory for Egocentric Streaming Video Assistants","abstract":"To serve as real-world personal assistants, streaming video models need persistent memory that retains past experiences for later use. Yet existing streaming benchmarks and methods often focus on individual continuous videos or short clips, overlooking that real-world interactions are often intermittent and require memory to persist across interruptions. To fill this gap, we introduce APM-Bench, which reformulates real-world streaming interaction as multi-session life trajectories. It contains 549 sessions, 104 trajectories, and 2,719 candidates, spanning both objective and open-ended questions. Each session is a video with fine-grained annotations, and sessions within a trajectory revolve around related activities. Models then use persistent memory to answer questions about past sessions and provide proactive responses while maintaining real-time interaction. This raises challenges: per"},{"id":"arxiv:2609.37969","topics":["Post-Training","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37969.pdf","authors":["Haozhe Liu","Tian Ye","Shuchen Xue","Yitong Li","Junsong Chen","Haopeng Li","Jincheng Yu","Duomin Wang","Ruihua Zhang","Lei Zhu","Song Han","Enze Xie"],"url":"https://arxiv.org/abs/2609.37969","hfUrl":"https://huggingface.co/papers/2609.37969","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37969","source":"arxiv","upvotes":28,"tags":["Post-Training","Evaluation"],"title":"SoL-Refiner: Speed-of-Light One-Step Refinement for High-Resolution Video","abstract":"High-resolution video generation is expensive, as its cost grows rapidly with the number of spatiotemporal tokens. A practical alternative first generates a lower-resolution video and then applies a refiner, but conventional multi-step refinement introduces a second sampling bottleneck. We present SoL-Refiner, a one-step video refiner that transforms low-resolution model outputs into 4K videos with a single denoising step. Our three-stage recipe combines high-resolution continual training, reinforcement learning (RL) post-training, and a final one-step distillation. We introduce Refiner-Bench, a video refinement benchmark constructed from the outputs of different video generators, and use a shared-input protocol to compare refiners at approximately 2K output resolution. At 2K, the one-step SoL-Refiner outperforms all external refiners on the VBench and UniPercept averages, while at $3840"},{"id":"arxiv:2609.37236","topics":["Post-Training","Evaluation"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37236.pdf","authors":["Ido Levy","Asaf Yehudai","Segev Shlomov","Asaf Adi","Leshem Choshen"],"url":"https://arxiv.org/abs/2609.37236","hfUrl":"https://huggingface.co/papers/2609.37236","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37236","source":"arxiv","upvotes":26,"tags":["Post-Training","Evaluation"],"title":"Asking for What Was Never Requested: Horizontal and Vertical Proactivity in Agents","abstract":"An agent that uses tools typically responds to what the user explicitly asks, yet completing the task may require information the user never requested. Work on proactive agents mainly studies whether and when an agent should act on its own, not what information it should pursue. We study a distinct axis of proactivity: its content. Horizontal proactivity pursues unstated information that the current context already identifies, and vertical proactivity pursues needs that only earlier evidence reveals. A need graph, recovered from a benchmark's own decomposition, records which needs depend on which, so both forms, and whether the agent stops at the right time, can be scored from a transcript without a model judge. To learn this behavior, we propose Q&D (questioner and drafter), which trains a questioner to prefer the question whose continuation retrieves more of the required evidence, with"},{"id":"arxiv:2609.36651","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36651.pdf","authors":["FangZhi Zhong","Xuerui Qiu","Yuqi Pan","Ya Liu","Shaowei Gu","Bo Xu","Guoqi Li"],"url":"https://arxiv.org/abs/2609.36651","hfUrl":"https://huggingface.co/papers/2609.36651","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.36651","source":"arxiv","upvotes":20,"tags":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"title":"FocusVTC: Efficient and High-Performance Visual Text Compression with Adaptive Resolution","abstract":"Long-context reasoning in large language models incurs substantial computation and memory costs. Visual text compression (VTC) reduces input length by rendering text as images, but fixed-resolution rendering creates a compression-performance trade-off: low DPI saves tokens at the expense of legibility, whereas high DPI spends tokens on irrelevant content. We introduce FocusVTC, which breaks this trade-off through adaptive resolution while preserving general multimodal capabilities. It combines compressed low-DPI global views with selective region enhancement, integrating enhanced views into ongoing reasoning. We construct 29.4K high-quality Reasoning-Evidence Localization (REL) chain-of-thought examples (REL-CoT) that link reasoning traces to page indices and bounding boxes. Multi-resolution REL supervised fine-tuning (REL-SFT) teaches the model to localize relevant regions, and Group Re"},{"id":"arxiv:2609.38157","topics":["LLM Training"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.38157.pdf","authors":["Kuan-Po Huang","Haohe Liu","Puyuan Peng","Haibin Wu","Zhaoheng Ni","Hung-yi Lee","Jinwon Lee","Neha Chachra"],"url":"https://arxiv.org/abs/2609.38157","hfUrl":"https://huggingface.co/papers/2609.38157","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.38157","source":"arxiv","upvotes":15,"tags":["LLM Training"],"title":"EmoRES-TTS: Residual-Enhanced Vector Steering for Emotional Speech Generation","abstract":"Emotion-conditioned text-to-speech (TTS) models may fail to express the requested emotion reliably, and improving controllability by additional training is costly in both computation and emotion-labeled speech training data. We therefore study vector steering, a training-free approach that modifies the internal representations of a frozen model. CoCoEmo, a conventional vector steering method for emotion TTS, treats each emotion vector as an indivisible direction controlled by a single global strength, limiting adherence to the requested emotion. In this work, we first discover that an emotion vector can be decomposed into a shared component that moves speech away from neutral expression and a residual component that directs generation toward the requested emotion. Building on this finding, we propose Emotion Residual-Enhanced Steering for TTS (EmoRES), a novel method that controls the tw"},{"id":"arxiv:2609.37040","topics":["Agent Safety","Fine-tuning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.37040.pdf","authors":["Federico Torrielli","Gianluca Barmina","Andrea Blasi Núñez","Amon Rapp","Luigi Di Caro","Peter Schneider-Kamp","Lukas Galke Poech"],"url":"https://arxiv.org/abs/2609.37040","hfUrl":"https://huggingface.co/papers/2609.37040","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.37040","source":"arxiv","upvotes":11,"tags":["Agent Safety","Fine-tuning"],"title":"Selecting The Most Informative Tokens in Natural Language Autoencoders","abstract":"Natural language autoencoders translate a language model's internal activations into readable explanations. Explaining every token position is costly. Which positions should an auditor inspect to understand a potential threat? We study this question across $4.7$ million explanations on prompt injection and concealment. We compare signals from model computation with a ranker trained only on chat structure. Chat structure usually selects more relevant explanations than the computational signals, without requiring a model forward pass for position selection. On three of four datasets, explaining just $5\\%$ of positions retains nearly all of the success rate from explaining every position, where success means obtaining an explanation about the threat. The benefit varies with the audit task. We also show that pretrained verbalizers recover words that models have learned to conceal through fin"},{"id":"arxiv:2609.36653","topics":["Reasoning"],"announceDate":"2026-09-30","date":"2026-09-30","pdf":"https://arxiv.org/pdf/2609.36653.pdf","authors":["Boyuan Wang","Chengyao Yu","Jiaxi Ren","Hongxin Wei","Bingyi Jing","Yuxin Tao"],"url":"https://arxiv.org/abs/2609.36653","hfUrl":"https://huggingface.co/papers/2609.36653","submittedDate":"2026-09-29","arxiv":"https://arxiv.org/abs/2609.36653","source":"arxiv","upvotes":10,"tags":["Reasoning"],"title":"Scheduling Recursive Reasoning in Looped Transformers","abstract":"Recurrent reasoning models have attracted growing attention for scaling test-time computation, typically by iteratively refining latent states with shared parameters. However, these models apply each learned update with a fixed unit scale, which can be conservative when updates make persistent progress and overly aggressive when they fluctuate, limiting the benefit of additional loops. To understand how the scale should vary along the trajectory, we first analyze the sensitivity of terminal loss to recurrent update scale. We show that its temporal average admits an exact decomposition into persistent-progress and centered-fluctuation contributions. Based on this, we introduce the Trajectory Adaptive Progress-Fluctuation Scheduler (TAPS), which tracks their balance across recurrent updates and adapts the step size online. Theoretically, we establish sufficient conditions under which TAPS "}],"archive":[],"latestPath":"data/latest.json"};
